atures disabled\n- Dev profile: --spring.profiles.active=dev for enhanced development settings","tree":{"sha":"daa04146621058badc4ee4decc168c699d2c6ab7","url":"https://api.github.com/repos/ecruz165/conversation-ui-assistant/git/trees/daa04146621058badc4ee4decc168c699d2c6ab7"},"url":"https://api.github.com/repos/ecruz165/conversation-ui-assistant/git/commits/dd646c239f61a40f4d047397132c83ce65b04015","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/26984958?v=4","events_url":"https://api.github.com/users/ecruz165/events{/privacy}","followers_url":"https://api.github.com/users/ecruz165/followers","following_url":"https://api.github.com/users/ecruz165/following{/other_user}","gists_url":"https://api.github.com/users/ecruz165/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ecruz165","id":26984958,"login":"ecruz165","node_id":"MDQ6VXNlcjI2OTg0OTU4","organizations_url":"https://api.github.com/users/ecruz165/orgs","received_events_url":"https://api.github.com/users/ecruz165/received_events","repos_url":"https://api.github.com/users/ecruz165/repos","site_admin":false,"starred_url":"https://api.github.com/users/ecruz165/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ecruz165/subscriptions","type":"User","url":"https://api.github.com/users/ecruz165","user_view_type":"public"},"html_url":"https://github.com/ecruz165/conversation-ui-assistant/commit/dd646c239f61a40f4d047397132c83ce65b04015","node_id":"C_kwDOP2SoVtoAKGRkNjQ2YzIzOWY2MWE0MGY0ZDA0NzM5NzEzMmM4M2NlNjViMDQwMTU","parents":[{"html_url":"https://github.com/ecruz165/conversation-ui-assistant/commit/06177dc068c3735bc280fde7b55f7201b89f7692","sha":"06177dc068c3735bc280fde7b55f7201b89f7692","url":"https://api.github.com/repos/ecruz165/conversation-ui-assistant/commits/06177dc068c3735bc280fde7b55f7201b89f7692"}],"sha":"dd646c239f61a40f4d047397132c83ce65b04015","